mapper.sql:
WHERE c.delete_yn = 'N'
  AND c.code_group_id = #{search.codeGroupId}

  AND c.use_yn = #{search.useYn}


  AND (c.code      LIKE CONCAT('%', #{search.keyword}, '%')
    OR c.code_name LIKE CONCAT('%', #{search.keyword}, '%'))

mapper.select:
SELECT COUNT(1) FROM tb_code
 WHERE code_group_id = #{codeGroupId}
   AND code          = #{code}
   AND delete_yn     = 'N'

  AND code_id <> #{excludeCodeId}
